const rotateSession = `-- name: RotateSession :execrows
UPDATE sessions
SET token_hash = $1, refresh_hash = $2,
    previous_refresh_hash = $3, refreshed_at = now(), last_used_at = now(),
    access_expires_at = $4,
    expires_at = least($5::timestamptz, coalesce(expires_cap, $5::timestamptz))
WHERE id = $6 AND refresh_hash = $3 AND revoked_at IS NULL
`

type RotateSessionParams struct {
	TokenHash       []byte
	RefreshHash     []byte
	OldRefreshHash  []byte
	AccessExpiresAt *time.Time
	ExpiresAt       time.Time
	ID              uuid.UUID
}

// Nouveau couple de jetons ; échoue (0 ligne) si un autre rafraîchissement est passé avant.
func (q *Queries) RotateSession(ctx context.Context, arg RotateSessionParams) (int64, error) {
	result, err := q.db.Exec(ctx, rotateSession,
		arg.TokenHash,
		arg.RefreshHash,
		arg.OldRefreshHash,
		arg.AccessExpiresAt,
		arg.ExpiresAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

