const upsertDevice = `-- name: UpsertDevice :one
INSERT INTO auth_devices (user_id, device_hash, name) VALUES ($1, $2, $3)
ON CONFLICT (user_id, device_hash) DO UPDATE
SET last_seen_at = now(), name = CASE WHEN EXCLUDED.name = '' THEN auth_devices.name ELSE EXCLUDED.name END
RETURNING id, (xmax = 0)::boolean AS inserted
`

type UpsertDeviceParams struct {
	UserID     uuid.UUID
	DeviceHash []byte
	Name       string
}

type UpsertDeviceRow struct {
	ID       uuid.UUID
	Inserted bool
}

// Appareil retrouvé ou ajouté ; inserted vaut vrai pour un nouvel appareil.
func (q *Queries) UpsertDevice(ctx context.Context, arg UpsertDeviceParams) (UpsertDeviceRow, error) {
	row := q.db.QueryRow(ctx, upsertDevice, arg.UserID, arg.DeviceHash, arg.Name)
	var i UpsertDeviceRow
	err := row.Scan(&i.ID, &i.Inserted)
	return i, err
}

